//! R9 opportunity precondition/reason matrix; review only.
use serde_json::json;
fn reason(spot:bool,fut:bool,age_s:f64,age_f:f64,src_s:i64,src_f:i64,max_age:f64,black:bool,ask:f64,bid:f64,minp:f64,maxp:f64,cost:f64,thr:f64,meta:&str)->&'static str{if !spot||!fut{return "SYSTEM_NOT_READY"}if age_s<0.||age_f<0.||age_s>max_age||age_f>max_age||src_s < -1000||src_f < -1000||src_s as f64>max_age||src_f as f64>max_age{return "STALE_BOOK"}if black{return "BLACKLIST"}if ask<minp||ask>maxp{return "PRICE_FILTER"}if(bid/ask-1.)*10000.-cost<thr{return "EDGE_TOO_LOW"}match meta{"SIZE_METADATA_READY"=>"CONTINUE","SIZE_METADATA_MISSING"=>"SIZE_METADATA_NOT_READY",x=>match x{"SIZE_METADATA_STALE"=>"SIZE_METADATA_STALE","SIZE_METADATA_INVALID"=>"SIZE_METADATA_INVALID","INSTRUMENT_INACTIVE"=>"INSTRUMENT_INACTIVE",_=>"SIZE_METADATA_INVALID"}}}
fn main(){let c=[("ready",true,true,1.,1.,1,1,false,100.,101.,"SIZE_METADATA_READY","CONTINUE"),("no_spot",false,true,1.,1.,1,1,false,100.,101.,"SIZE_METADATA_READY","SYSTEM_NOT_READY"),("stale_recv",true,true,801.,1.,1,1,false,100.,101.,"SIZE_METADATA_READY","STALE_BOOK"),("future_recv",true,true,-1.,1.,1,1,false,100.,101.,"SIZE_METADATA_READY","STALE_BOOK"),("stale_source",true,true,1.,1.,801,1,false,100.,101.,"SIZE_METADATA_READY","STALE_BOOK"),("black",true,true,1.,1.,1,1,true,100.,101.,"SIZE_METADATA_READY","BLACKLIST"),("price",true,true,1.,1.,1,1,false,0.1,0.101,"SIZE_METADATA_READY","PRICE_FILTER"),("edge",true,true,1.,1.,1,1,false,100.,100.5,"SIZE_METADATA_READY","EDGE_TOO_LOW"),("meta_missing",true,true,1.,1.,1,1,false,100.,101.,"SIZE_METADATA_MISSING","SIZE_METADATA_NOT_READY"),("meta_stale",true,true,1.,1.,1,1,false,100.,101.,"SIZE_METADATA_STALE","SIZE_METADATA_STALE"),("inactive",true,true,1.,1.,1,1,false,100.,101.,"INSTRUMENT_INACTIVE","INSTRUMENT_INACTIVE")];let mut f=vec![];for(n,s,u,a,b,x,y,k,ask,bid,m,w)in c{let g=reason(s,u,a,b,x,y,800.,k,ask,bid,1.,1000000.,20.,42.,m);if g!=w{f.push(json!({"case":n,"got":g,"want":w}))}}println!("{}",json!({"r9_reason_gate":f.is_empty(),"cases":11,"failures":f,"trading":false}));}